setup:
cat > ${EVIDENCE}/ipsec/gwa/strongswan.conf <<'EOF'
charon {
  load = random nonce openssl pem pkcs1 x509 pubkey gcm aes sha1 sha2 hmac curve25519 kdf kernel-libipsec kernel-netlink socket-default vici
  filelog {
    gwa {
      path = ${EVIDENCE}/ipsec/gwa/charon.log
      time_format = %H:%M:%S
      default = 1
      flush_line = yes
    }
  }
  plugins {
    vici {
      socket = unix://${EVIDENCE}/ipsec/gwa/charon.vici
    }
    kernel-libipsec {
      raw_esp = yes
    }
  }
}
EOF
cat > ${EVIDENCE}/ipsec/gwb/strongswan.conf <<'EOF'
charon {
  load = random nonce openssl pem pkcs1 x509 pubkey gcm aes sha1 sha2 hmac curve25519 kdf kernel-libipsec kernel-netlink socket-default vici
  filelog {
    gwb {
      path = ${EVIDENCE}/ipsec/gwb/charon.log
      time_format = %H:%M:%S
      default = 1
      flush_line = yes
    }
  }
  plugins {
    vici {
      socket = unix://${EVIDENCE}/ipsec/gwb/charon.vici
    }
    kernel-libipsec {
      raw_esp = yes
    }
  }
}
EOF
cat > ${EVIDENCE}/ipsec/gwa/swanctl.conf <<'EOF'
connections {
  site-b {
    local_addrs = 198.18.190.1
    remote_addrs = 198.18.191.1
    proposals = aes256-sha256-x25519
    local {
      auth = psk
      id = gw-a
    }
    remote {
      auth = psk
      id = gw-b
    }
    children {
      lan-b {
        local_ts = 10.1.1.0/24
        remote_ts = 10.2.1.0/24
        esp_proposals = aes256gcm16-x25519
      }
    }
  }
}
secrets {
  ike-ab {
    id-a = gw-a
    id-b = gw-b
    secret = "course-psk-not-for-production"
  }
}
EOF
cat > ${EVIDENCE}/ipsec/gwb/swanctl.conf <<'EOF'
connections {
  site-a {
    local_addrs = 198.18.191.1
    remote_addrs = 198.18.190.1
    proposals = aes256-sha256-x25519
    local {
      auth = psk
      id = gw-b
    }
    remote {
      auth = psk
      id = gw-a
    }
    children {
      lan-a {
        local_ts = 10.2.1.0/24
        remote_ts = 10.1.1.0/24
        esp_proposals = aes256gcm16-x25519
      }
    }
  }
}
secrets {
  ike-ab {
    id-a = gw-a
    id-b = gw-b
    secret = "course-psk-not-for-production"
  }
}
EOF
